import catalog from '@/content/plugin-catalog.json';

/**
 * The playbooks the ChatGPT plugin may serve, with the license notice each needs.
 *
 * src/content/plugin-catalog.json is generated by `npm run license:audit`; don't
 * edit it by hand. A playbook that isn't listed isn't served, so new playbooks
 * stay out of the plugin until the audit has passed them.
 */
export interface PlaybookLicense {
  name: string;
  copyright?: string;
  url: string;
  notice: string;
}

const licenses = new Map<string, PlaybookLicense>(Object.entries(catalog.licenses));
const playbooks = new Map<string, string>(Object.entries(catalog.playbooks));

export function getPlaybookLicense(slug: string): PlaybookLicense | null {
  const file = playbooks.get(slug);
  return file ? (licenses.get(file) ?? null) : null;
}
